// Fixtures were generated by test/fixtures/generate_fixtures.py with Pillow,
// an EXIF writer independent of the reader under test. They are synthetic
// solid-colour images created for this package (no third-party images).
import 'dart:io';

import 'package:exif_kit/exif_kit.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  Future<ExifData> load(String name) => ExifKit.readFile('test/fixtures/$name');

  test('pillow_ii.jpg (little-endian)', () async {
    final d = await load('pillow_ii.jpg');
    expect(d.make, 'Canon');
    expect(d.model, 'Canon EOS 80D');
    expect(d.software, 'fixture-gen 1.0');
    expect(d.orientation, ExifOrientation.rotate90);
    expect(d.rotationDegrees, 90);
    expect(d.latitude, closeTo(51 + 30 / 60 + 12.34 / 3600, 1e-9));
    expect(d.longitude, closeTo(-(7 / 60 + 39.60 / 3600), 1e-9));
    expect(d.altitude, closeTo(35, 1e-9));
    expect(d.dateTimeOriginal, DateTime(2024, 5, 6, 7, 8, 9, 250));
    expect(d.offsetTimeOriginal, const Duration(hours: 1));
    expect(d.dateTimeOriginalUtc, DateTime.utc(2024, 5, 6, 6, 8, 9, 250));
    expect(d.exposureTime, closeTo(1 / 125, 1e-12));
    expect(d.fNumber, closeTo(2.8, 1e-12));
    expect(d.iso, 400);
    expect(d.focalLength, closeTo(50, 1e-12));
    expect(d.width, 64);
    expect(d.height, 48);
  });

  test('pillow_mm.jpg (big-endian)', () async {
    final d = await load('pillow_mm.jpg');
    expect(d.make, 'NIKON CORPORATION');
    expect(d.model, 'NIKON D750');
    expect(d.orientation, ExifOrientation.rotate270);
    expect(d.latitude, closeTo(-(33 + 52 / 60 + 48 / 3600), 1e-9));
    expect(d.longitude, closeTo(151 + 12 / 60 + 36 / 3600, 1e-9));
    expect(d.altitude, closeTo(-12.5, 1e-9));
    expect(d.dateTimeOriginal, DateTime(2019, 12, 31, 23, 59, 58));
    expect(d.offsetTimeOriginal, -const Duration(hours: 5, minutes: 30));
    expect(d.dateTimeOriginalUtc, DateTime.utc(2020, 1, 1, 5, 29, 58));
    expect(d.exposureTime, closeTo(1 / 4000, 1e-12));
    expect(d.fNumber, 4);
    expect(d.iso, 100);
    expect(d.focalLength, closeTo(24.5, 1e-12));
    expect(d.width, 40);
    expect(d.height, 30);
  });

  test('no_exif.jpg', () async {
    final d = await load('no_exif.jpg');
    expect(d.make, isNull);
    expect(d.latitude, isNull);
    expect(d.width, 8);
  });

  test('missing file throws ExifFileNotFoundException', () async {
    await expectLater(ExifKit.readFile('test/fixtures/nope.jpg'),
        throwsA(isA<ExifFileNotFoundException>()));
  });

  test('fixtures are real JPEG files', () {
    for (final n in ['pillow_ii.jpg', 'pillow_mm.jpg', 'no_exif.jpg']) {
      final b = File('test/fixtures/$n').readAsBytesSync();
      expect(b.sublist(0, 2), [0xFF, 0xD8], reason: n);
      expect(b.sublist(b.length - 2), [0xFF, 0xD9], reason: n);
    }
  });
}
